import React, { useEffect, useState } from 'react';
import axios from 'axios';

function MenuPage() {
  const [produtos, setProdutos] = useState([]);

  useEffect(() => {
    axios.get('https://api.unifor-exchange.com/produtos')
      .then(response => setProdutos(response.data))
      .catch(error => console.error('Erro ao carregar produtos', error));
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 p-8">
      <h1 className="text-3xl font-bold text-center text-blue-600 mb-8">
        Catálogo de Produtos
      </h1>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
        {produtos.map((produto) => (
          <div key={produto.id} className="bg-white rounded-lg shadow-md p-4 flex flex-col">
            <img
              src={produto.imagem || "https://via.placeholder.com/150"}
              alt={produto.nome}
              className="w-full h-40 object-cover rounded mb-4"
            />
            <h2 className="text-lg font-semibold mb-2">{produto.nome}</h2>
            <p className="text-gray-600 mb-2">{produto.descricao}</p>
            <p className="text-blue-600 font-bold mb-4">R$ {produto.preco}</p>
            <button className="bg-blue-500 text-white py-2 rounded hover:bg-blue-600 transition duration-200">
              Ver detalhes
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default MenuPage;
